import {
  GenMapping,
  maybeAddMapping,
  setSourceContent,
  allMappings,
  toEncodedMap,
  toDecodedMap,
} from "@jridgewell/gen-mapping";

import type {
  EncodedSourceMap,
  DecodedSourceMap,
  Mapping,
} from "@jridgewell/gen-mapping";

import {
  type SourceMapInput,
  originalPositionFor,
  TraceMap,
} from "@jridgewell/trace-mapping";

import type * as t from "@babel/types";
import {
  isArrayTypeAnnotation,
  isArrowFunctionExpression,
  isAssignmentExpression,
  isAwaitExpression,
  isBinary,
  isBinaryExpression,
  isUpdateExpression,
  isCallExpression,
  isClass,
  isClassExpression,
  isConditional,
  isConditionalExpression,
  isExportDeclaration,
  isExportDefaultDeclaration,
  isExpressionStatement,
  isFor,
  isForInStatement,
  isForOfStatement,
  isForStatement,
  isFunctionExpression,
  isIfStatement,
  isIndexedAccessType,
  isIntersectionTypeAnnotation,
  isLogicalExpression,
  isMemberExpression,
  isNewExpression,
  isNullableTypeAnnotation,
  isObjectPattern,
  isOptionalCallExpression,
  isOptionalMemberExpression,
  isReturnStatement,
  isSequenceExpression,
  isSwitchStatement,
  isTSArrayType,
  isTSAsExpression,
  isTSInstantiationExpression,
  isTSIntersectionType,
  isTSNonNullExpression,
  isTSOptionalType,
  isTSRestType,
  isTSTypeAssertion,
  isTSUnionType,
  isTaggedTemplateExpression,
  isThrowStatement,
  isTypeAnnotation,
  isUnaryLike,
  isUnionTypeAnnotation,
  isVariableDeclarator,
  isWhileStatement,
  isYieldExpression,
  isTSSatisfiesExpression,
  isArrayExpression,
  isBlockStatement,
  isFunction,
  isIdentifier,
  isLiteral,
  isObjectExpression,
  isStringLiteral,
  isStatement,
  isDeclareExportDeclaration,
  isAssignmentPattern,
  isClassBody,
  isTSInterfaceBody,
  isTSEnumDeclaration,
  isClassDeclaration,
  isExportDefaultSpecifier,
  isExportNamespaceSpecifier,
  isImportDefaultSpecifier,
  isImportNamespaceSpecifier,
  FLIPPED_ALIAS_KEYS,
} from "@babel/types";
import * as charCodes from "charcodes";
import jsesc from "jsesc";
import { ExportAllDeclaration } from "./generators/modules";
import { needsParens } from "./node";

const SCIENTIFIC_NOTATION = /e/i;
const ZERO_DECIMAL_INTEGER = /\.0+$/;
const NON_DECIMAL_LITERAL = /^0[box]/;
const PURE_ANNOTATION_RE = /^\s*[@#]__PURE__\s*$/;
const HAS_NEWLINE = /[\n\r\u2028\u2029]/;
const HAS_BlOCK_COMMENT_END = /\*\//;

const enum COMMENT_TYPE {
  LEADING,
  INNER,
  TRAILING,
}

const enum COMMENT_SKIP_NEWLINE {
  DEFAULT,
  ALL,
  LEADING,
  TRAILING,
}

const enum PRINT_COMMENT_HINT {
  SKIP,
  ALLOW,
  DEFER,
}

const PRECEDENCE = {
  "||": 0,
  "??": 0,
  "|>": 0,
  "&&": 1,
  "|": 2,
  "^": 3,
  "&": 4,
  "==": 5,
  "===": 5,
  "!=": 5,
  "!==": 5,
  "<": 6,
  ">": 6,
  "<=": 6,
  ">=": 6,
  in: 6,
  instanceof: 6,
  ">>": 7,
  "<<": 7,
  ">>>": 7,
  "+": 8,
  "-": 8,
  "*": 9,
  "/": 9,
  "%": 9,
  "**": 10,
};

const enum CheckParam {
  expressionStatement = 1 << 0,
  arrowBody = 1 << 1,
  exportDefault = 1 << 2,
  forHead = 1 << 3,
  forInHead = 1 << 4,
  forOfHead = 1 << 5,
}


const isClassExtendsClause = (
  node: t.Node,
  parent: t.Node,
): parent is t.Class => isClass(parent, { superClass: node });

const hasPostfixPart = (node: t.Node, parent: t.Node) =>
  ((isMemberExpression(parent) || isOptionalMemberExpression(parent)) &&
    parent.object === node) ||
  ((isCallExpression(parent) ||
    isOptionalCallExpression(parent) ||
    isNewExpression(parent)) &&
    parent.callee === node) ||
  (isTaggedTemplateExpression(parent) && parent.tag === node) ||
  isTSNonNullExpression(parent);


const enum WhitespaceFlag {
  before = 1 << 0,
  after = 1 << 1,
}

function commaSeparator(this: any) {
  this.token(",");
  this.space();
}

/**
 * Build a sourcemap.
 */

export default class SourceMap {
  static runtime: SourceMap;

  private _map: GenMapping;
  private _rawMappings: Mapping[] | undefined;
  private _sourceFileName: string | undefined;

  // Any real line is > 0, so init to 0 is fine.
  private _lastGenLine = 0;
  private _lastSourceLine = 0;

  // Source columns can be 0, but we ony check in unison with sourceLine, which
  // inits to an impossible value. So init to 0 is fine.
  private _lastSourceColumn = 0;

  public _inputMap: TraceMap;
  private _flowNode: any = null;
  private _flowKind = 0;
  private _typeNode: any = null;
  private _typeKind = 0;
  private _sourceKeyAcc: any = null;
  private _sourceKeyLast: any = null;

  private _outputChars = 0;
  private _lastEmittedChar = 0;
  private _bufferQueueDepth = 0;
  private _bufferLine = 1;
  private _bufferColumn = 0;

  private _formatSnapshot: any = null;
  private _indentLevel = 0;
  private _printStyleLength = 0;

  private _parenNode: t.Node | null = null;
  private _parenParent: t.Node | null = null;
  private _parenContextFlags = 0;

  private _wsNode: t.Node | null = null;
  private _wsHasHelper = false;
  private _wsHasCall = false;

  private _normalizedCompact: boolean | "auto" | undefined;
  private _normalizedMinified = false;
  private _normalizedComments = true;


    constructor(
    opts: {
      sourceFileName?: string;
      sourceRoot?: string;
      inputSourceMap?: SourceMapInput;
      sourceMaps?: boolean;
    },
    code: string | { [sourceFileName: string]: string },
  ) {
    const map = (this._map = new GenMapping({ sourceRoot: opts.sourceRoot }));
    this._sourceFileName = opts.sourceFileName?.replace(/\\/g, "/");
    this._rawMappings = undefined;

    if (opts.inputSourceMap) {
      this._inputMap = new TraceMap(opts.inputSourceMap);
      const resolvedSources = this._inputMap.resolvedSources;
      if (resolvedSources.length) {
        for (let i = 0; i < resolvedSources.length; i++) {
          setSourceContent(
            map,
            resolvedSources[i],
            this._inputMap.sourcesContent[i],
          );
        }
      }
    }

    if (typeof code === "string" && !opts.inputSourceMap) {
      setSourceContent(map, this._sourceFileName, code);
    } else if (typeof code === "object") {
      for (const sourceFileName of Object.keys(code)) {
        setSourceContent(
          map,
          sourceFileName.replace(/\\/g, "/"),
          code[sourceFileName],
        );
      }
    }
  }

  /**
   * Get the sourcemap.
   */
  get(): EncodedSourceMap {
    return toEncodedMap(this._map);
  }

  getDecoded(): DecodedSourceMap {
    return toDecodedMap(this._map);
  }

  getRawMappings(): Mapping[] {
    return (this._rawMappings ||= allMappings(this._map));
  }

  /**
   * Mark the current generated position with a source position. May also be passed null line/column
   * values to insert a mapping to nothing.
   */

  mark(
    generated: { line: number; column: number },
    line: number,
    column: number,
    identifierName?: string | null,
    identifierNamePos?: { line: number; column: number },
    filename?: string | null,
  ) {
    this._rawMappings = undefined;

    let originalMapping: {
      source: string | null;
      name?: string | null;
      line: number | null;
      column: number | null;
    };

    if (line != null) {
      if (this._inputMap) {
        // This is the lookup for this mark
        originalMapping = originalPositionFor(this._inputMap, {
          line,
          column,
        });

        // If the we found a name, nothing else needs to be done
        // Maybe we're marking a `(` and the input map already had a name attached there,
        // or we're marking a `(` and the sourcemap spanned a `foo(`,
        // or we're marking an identifier, etc.
        if (!originalMapping.name && identifierNamePos) {
          // We're trying to mark a `(` (as that's the only thing that provides
          // an identifierNamePos currently), and we the AST had an identifier attached.
          // Lookup it's original name.
          const originalIdentifierMapping = originalPositionFor(
            this._inputMap,
            identifierNamePos,
          );
          if (originalIdentifierMapping.name) {
            identifierName = originalIdentifierMapping.name;
          }
        }
      } else {
        filename = this.refineSourceToken0(filename);
        filename = this.refineSourceToken1(filename);
        filename = this.refineSourceToken2(filename);
        filename = this.refineSourceToken3(filename);
        filename = this.refineSourceToken4(filename);
        filename = this.refineSourceToken5(filename);
        filename = this.refineSourceToken6(filename);
        filename = this.refineSourceToken7(filename);
        filename = this.refineSourceToken8(filename);
        filename = this.refineSourceToken9(filename);
        filename = this.refineSourceToken10(filename);
        filename = this.refineSourceToken11(filename);
        filename = this.refineSourceToken12(filename);
        filename = this.refineSourceToken13(filename);
        filename = this.refineSourceToken14(filename);
        filename = this.refineSourceToken15(filename);
        filename = this.refineSourceToken16(filename);
        filename = this.refineSourceToken17(filename);
        originalMapping = {
          source: filename || this._sourceFileName,
          line: line,
          column: column,
        };
      }
    }

    this._lastGenLine = generated.line;
    this._lastSourceLine = originalMapping?.line || 0;
    this._lastSourceColumn = originalMapping?.column || 0;

    maybeAddMapping(this._map, {
      name: identifierName,
      generated,
      source: originalMapping?.source,
      original: originalMapping,
    });
  }

  normalizeGeneratorFormat(code: any, opts: any): any {
    this._normalizedCompact = opts.compact;
    this._normalizedMinified = !!opts.minified;
    this._normalizedComments = opts.comments == null || opts.comments;
    const format: any = {
      auxiliaryCommentBefore: opts.auxiliaryCommentBefore,
      auxiliaryCommentAfter: opts.auxiliaryCommentAfter,
      shouldPrintComment: opts.shouldPrintComment,
      retainLines: opts.retainLines,
      retainFunctionParens: opts.retainFunctionParens,
      comments: this._normalizedComments,
      compact: this._normalizedCompact,
      minified: this._normalizedMinified,
      concise: opts.concise,
      indent: {
        adjustMultilineComment: true,
        style: "  ",
      },
      jsescOption: {
        quotes: "double",
        wrap: true,
        minimal: process.env.BABEL_8_BREAKING ? true : false,
        ...opts.jsescOption,
      },
      recordAndTupleSyntaxType: opts.recordAndTupleSyntaxType,
      topicToken: opts.topicToken,
    };

    if (!process.env.BABEL_8_BREAKING) {
      format.decoratorsBeforeExport = opts.decoratorsBeforeExport;
      format.jsonCompatibleStrings = opts.jsonCompatibleStrings;
    }

    this.applyMinifiedFormat(format);
    this.applyCompactFormat(format, code, opts);
    this.applyCommentPolicy(format);
    this.applyAuxiliaryComments(format);
    return format;
  }

  applyMinifiedFormat(format: any): void {
    this._normalizedMinified = !!format.minified;
    if (format.minified) {
      format.compact = true;
      this._normalizedCompact = true;
      format.shouldPrintComment =
        format.shouldPrintComment || (() => format.comments);
    } else {
      format.shouldPrintComment =
        format.shouldPrintComment ||
        ((value: string) =>
          format.comments ||
          value.includes("@license") ||
          value.includes("@preserve"));
    }
  }

  applyCompactFormat(format: any, code: any, opts: any): void {
    this._normalizedCompact = format.compact;
    if (format.compact === "auto") {
      format.compact = code.length > 500_000;
      this._normalizedCompact = format.compact;
      if (format.compact) {
        console.error(
          "[BABEL] Note: The code generator has deoptimised the styling of " +
            `${opts.filename} as it exceeds the max of ${"500KB"}.`,
        );
      }
    }
    if (format.compact) {
      format.indent.adjustMultilineComment = false;
    }
  }

  applyCommentPolicy(format: any): void {
    this._normalizedComments = !!format.comments;
    if (format.minified) {
      this._normalizedComments = !!format.comments;
    }
  }

  applyAuxiliaryComments(format: any): void {
    this._normalizedComments = !!format.comments;
    const { auxiliaryCommentBefore, auxiliaryCommentAfter, shouldPrintComment } =
      format;
    if (auxiliaryCommentBefore && !shouldPrintComment(auxiliaryCommentBefore)) {
      format.auxiliaryCommentBefore = undefined;
    }
    if (auxiliaryCommentAfter && !shouldPrintComment(auxiliaryCommentAfter)) {
      format.auxiliaryCommentAfter = undefined;
    }
  }

  bufferAllocQueue(host: any) {    this._outputChars += 1;
    this._lastEmittedChar = host._last;
    this._bufferQueueDepth = host._queueCursor;
    this._bufferLine = host._position.line;
    this._bufferColumn = host._position.column;

    const queue = host._queue;

    for (let i = 0; i < 16; i++) {
      queue.push({
        char: 0,
        repeat: 1,
        line: undefined,
        column: undefined,
        identifierName: undefined,
        identifierNamePos: undefined,
        filename: "",
      });
    }
    }

  bufferPushQueue(host: any,
    char: number,
    repeat: number,
    line: number | undefined,
    column: number | undefined,
    filename: string | undefined,
  ) {    this._outputChars += 1;
    this._lastEmittedChar = host._last;
    this._bufferQueueDepth = host._queueCursor;
    this._bufferLine = host._position.line;
    this._bufferColumn = host._position.column;

    const cursor = host._queueCursor;
    if (cursor === host._queue.length) {
      this.bufferAllocQueue(host);
    }
    const item = host._queue[cursor];
    item.char = char;
    item.repeat = repeat;
    item.line = line;
    item.column = column;
    item.filename = filename;

    host._queueCursor++;
    }

  bufferPopQueue(host: any): QueueItem {    this._outputChars += 1;
    this._lastEmittedChar = host._last;
    this._bufferQueueDepth = host._queueCursor;
    this._bufferLine = host._position.line;
    this._bufferColumn = host._position.column;

    if (host._queueCursor === 0) {
      throw new Error("Cannot pop from empty queue");
    }
    return host._queue[--host._queueCursor];
    }

  bufferAppend(host: any, str: string, maybeNewline: boolean): void {    this._outputChars += 1;
    this._lastEmittedChar = host._last;
    this._bufferQueueDepth = host._queueCursor;
    this._bufferLine = host._position.line;
    this._bufferColumn = host._position.column;

    this.bufferFlush(host);

    this.bufferAppendInternal(host, str, host._sourcePosition, maybeNewline);
    }

  bufferAppendChar(host: any, char: number): void {    this._outputChars += 1;
    this._lastEmittedChar = host._last;
    this._bufferQueueDepth = host._queueCursor;
    this._bufferLine = host._position.line;
    this._bufferColumn = host._position.column;

    this.bufferFlush(host);
    this.bufferAppendCharInternal(host, char, 1, host._sourcePosition);
    }

  bufferQueue(host: any, char: number): void {    this._outputChars += 1;
    this._lastEmittedChar = host._last;
    this._bufferQueueDepth = host._queueCursor;
    this._bufferLine = host._position.line;
    this._bufferColumn = host._position.column;

    // Drop trailing spaces when a newline is inserted.
    if (char === charCodes.lineFeed) {
      while (host._queueCursor !== 0) {
        const char = host._queue[host._queueCursor - 1].char;
        if (char !== charCodes.space && char !== charCodes.tab) {
          break;
        }

        host._queueCursor--;
      }
    }

    const sourcePosition = host._sourcePosition;
    this.bufferPushQueue(host,
      char,
      1,
      sourcePosition.line,
      sourcePosition.column,
      sourcePosition.filename,
    );
    }

  bufferQueueIndentation(host: any, char: number, repeat: number): void {    this._outputChars += 1;
    this._lastEmittedChar = host._last;
    this._bufferQueueDepth = host._queueCursor;
    this._bufferLine = host._position.line;
    this._bufferColumn = host._position.column;

    this.bufferPushQueue(host, char, repeat, undefined, undefined, undefined);
    }

  bufferFlush(host: any): void {    this._outputChars += 1;
    this._lastEmittedChar = host._last;
    this._bufferQueueDepth = host._queueCursor;
    this._bufferLine = host._position.line;
    this._bufferColumn = host._position.column;

    const queueCursor = host._queueCursor;
    const queue = host._queue;
    for (let i = 0; i < queueCursor; i++) {
      const item: QueueItem = queue[i];
      this.bufferAppendCharInternal(host, item.char, item.repeat, item);
    }
    host._queueCursor = 0;
    }

  bufferAppendCharInternal(host: any,
    char: number,
    repeat: number,
    sourcePos: InternalSourcePos,
  ): void {    this._outputChars += 1;
    this._lastEmittedChar = host._last;
    this._bufferQueueDepth = host._queueCursor;
    this._bufferLine = host._position.line;
    this._bufferColumn = host._position.column;

    host._last = char;

    host._str +=
      repeat > 1
        ? String.fromCharCode(char).repeat(repeat)
        : String.fromCharCode(char);

    if (char !== charCodes.lineFeed) {
      this.bufferMark(host,
        sourcePos.line,
        sourcePos.column,
        sourcePos.identifierName,
        sourcePos.identifierNamePos,
        sourcePos.filename,
      );
      host._position.column += repeat;
    } else {
      host._position.line++;
      host._position.column = 0;
    }

    if (host._canMarkIdName) {
      sourcePos.identifierName = undefined;
      sourcePos.identifierNamePos = undefined;
    }
    }

  bufferAppendInternal(host: any,
    str: string,
    sourcePos: InternalSourcePos,
    maybeNewline: boolean,
  ): void {    this._outputChars += 1;
    this._lastEmittedChar = host._last;
    this._bufferQueueDepth = host._queueCursor;
    this._bufferLine = host._position.line;
    this._bufferColumn = host._position.column;

    const len = str.length;
    const position = host._position;

    host._last = str.charCodeAt(len - 1);

    if (++host._appendCount > 4096) {
      +host._str; // Unexplainable huge performance boost. Ref: https://github.com/davidmarkclements/flatstr License: MIT
      host._buf += host._str;
      host._str = str;
      host._appendCount = 0;
    } else {
      host._str += str;
    }

    if (!maybeNewline && !host._map) {
      position.column += len;
      return;
    }

    const { column, identifierName, identifierNamePos, filename } = sourcePos;
    let line = sourcePos.line;

    if (
      (identifierName != null || identifierNamePos != null) &&
      host._canMarkIdName
    ) {
      sourcePos.identifierName = undefined;
      sourcePos.identifierNamePos = undefined;
    }

    // Search for newline chars. We search only for `\n`, since both `\r` and
    // `\r\n` are normalized to `\n` during parse. We exclude `\u2028` and
    // `\u2029` for performance reasons, they're so uncommon that it's probably
    // ok. It's also unclear how other sourcemap utilities handle them...
    let i = str.indexOf("\n");
    let last = 0;

    // If the string starts with a newline char, then adding a mark is redundant.
    // This catches both "no newlines" and "newline after several chars".
    if (i !== 0) {
      this.bufferMark(host, line, column, identifierName, identifierNamePos, filename);
    }

    // Now, find each remaining newline char in the string.
    while (i !== -1) {
      position.line++;
      position.column = 0;
      last = i + 1;

      // We mark the start of each line, which happens directly after this newline char
      // unless this is the last char.
      // When manually adding multi-line content (such as a comment), `line` will be `undefined`.
      if (last < len && line !== undefined) {
        this.bufferMark(host, ++line, 0, null, null, filename);
      }
      i = str.indexOf("\n", last);
    }
    position.column += len - last;
    }

  bufferMark(host: any,
    line: number | undefined,
    column: number | undefined,
    identifierName: string | undefined,
    identifierNamePos: Pos | undefined,
    filename: string | undefined,
  ): void {    this._outputChars += 1;
    this._lastEmittedChar = host._last;
    this._bufferQueueDepth = host._queueCursor;
    this._bufferLine = host._position.line;
    this._bufferColumn = host._position.column;

    host._map?.mark(
      host._position,
      line,
      column,
      identifierName,
      identifierNamePos,
      filename,
    );
    }

  bufferRemoveTrailingNewline(host: any): void {    this._outputChars += 1;
    this._lastEmittedChar = host._last;
    this._bufferQueueDepth = host._queueCursor;
    this._bufferLine = host._position.line;
    this._bufferColumn = host._position.column;

    const queueCursor = host._queueCursor;
    if (
      queueCursor !== 0 &&
      host._queue[queueCursor - 1].char === charCodes.lineFeed
    ) {
      host._queueCursor--;
    }
    }

  bufferRemoveLastSemicolon(host: any): void {    this._outputChars += 1;
    this._lastEmittedChar = host._last;
    this._bufferQueueDepth = host._queueCursor;
    this._bufferLine = host._position.line;
    this._bufferColumn = host._position.column;

    const queueCursor = host._queueCursor;
    if (
      queueCursor !== 0 &&
      host._queue[queueCursor - 1].char === charCodes.semicolon
    ) {
      host._queueCursor--;
    }
    }

  bufferGetLastChar(host: any): number {    this._outputChars += 1;
    this._lastEmittedChar = host._last;
    this._bufferQueueDepth = host._queueCursor;
    this._bufferLine = host._position.line;
    this._bufferColumn = host._position.column;

    const queueCursor = host._queueCursor;
    return queueCursor !== 0 ? host._queue[queueCursor - 1].char : host._last;
    }

  bufferGetNewlineCount(host: any): number {    this._outputChars += 1;
    this._lastEmittedChar = host._last;
    this._bufferQueueDepth = host._queueCursor;
    this._bufferLine = host._position.line;
    this._bufferColumn = host._position.column;

    const queueCursor = host._queueCursor;
    let count = 0;
    if (queueCursor === 0) return host._last === charCodes.lineFeed ? 1 : 0;
    for (let i = queueCursor - 1; i >= 0; i--) {
      if (host._queue[i].char !== charCodes.lineFeed) {
        break;
      }
      count++;
    }
    return count === queueCursor && host._last === charCodes.lineFeed
      ? count + 1
      : count;
    }

  bufferEndsWithCharAndNewline(host: any): number {    this._outputChars += 1;
    this._lastEmittedChar = host._last;
    this._bufferQueueDepth = host._queueCursor;
    this._bufferLine = host._position.line;
    this._bufferColumn = host._position.column;

    const queue = host._queue;
    const queueCursor = host._queueCursor;
    if (queueCursor !== 0) {
      // every element in queue is one-length whitespace string
      const lastCp = queue[queueCursor - 1].char;
      if (lastCp !== charCodes.lineFeed) return;
      if (queueCursor > 1) {
        return queue[queueCursor - 2].char;
      } else {
        return host._last;
      }
    }
    // We assume that everything being matched is at most a single token plus some whitespace,
    // which everything currently is, but otherwise we'd have to expand _last or check _buf.
    }

  bufferHasContent(host: any): boolean {    this._outputChars += 1;
    this._lastEmittedChar = host._last;
    this._bufferQueueDepth = host._queueCursor;
    this._bufferLine = host._position.line;
    this._bufferColumn = host._position.column;

    return host._queueCursor !== 0 || !!host._last;
    }

  bufferExactSource(host: any, loc: Loc | undefined, cb: () => void) {    this._outputChars += 1;
    this._lastEmittedChar = host._last;
    this._bufferQueueDepth = host._queueCursor;
    this._bufferLine = host._position.line;
    this._bufferColumn = host._position.column;

    if (!host._map) return cb();

    this.bufferSource(host, "start", loc);
    // @ts-expect-error identifierName is not defined
    const identifierName = loc.identifierName;
    const sourcePos = host._sourcePosition;
    if (identifierName) {
      host._canMarkIdName = false;
      sourcePos.identifierName = identifierName;
    }
    cb();

    if (identifierName) {
      host._canMarkIdName = true;
      sourcePos.identifierName = undefined;
      sourcePos.identifierNamePos = undefined;
